public class SurgePricing
{
    private readonly PricingStrategy _strategy;

    public decimal Calculate(SurgeContext ctx)
    {
        var demand = ctx.ActiveOrdersInArea / ctx.AvailablePartnersInArea;
        var multiplier = _strategy.GetMultiplier(demand);
        return ctx.BasePrice * multiplier;
    }
}

public class PartnerMatcher
{
    public async Task<Guid?> MatchAsync(Order order)
    {
        var candidates = _partners.GetAvailableNear(order.Restaurant.Location);
        return candidates
            .OrderBy(p => Distance(p.Location, order.Restaurant.Location))
            .ThenBy(p => p.Rating)
            .FirstOrDefault()?.Id;
    }
}

public class NotificationService
{
    public async Task SendAsync(Guid userId, string title, string body)
    {
        var tokens = _userTokens[userId];
        foreach (var token in tokens)
            _pushProvider.Send(token, title, body);
    }
}
